-- axes
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('tresc/motyw', 'treść/motyw', 'co pojawia się w świecie tekstu: miłość, ciało, noc, woda, dom, śmierć itd.', 'lapis', 1);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('sensoryka/bodzce', 'sensoryka/bodźce', 'jak tekst koduje natężenie, jakość i poszukiwanie bodźców oraz doświadczenie ciała.', 'lapis', 2);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('relacja/spoleczne', 'relacja/społeczne', 'kontakt, niedopasowanie, bliskość, samotność, role i komunikacja.', 'sliwka', 3);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('poznanie/uwaga/pamiec', 'poznanie/uwaga/pamięć', 'tok myślenia, skupienie, pamięć, organizacja, czas poznawczy.', 'ochra', 4);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('regulacja/bezpieczenstwo', 'regulacja/bezpieczeństwo', 'zejście napięcia, spokój, schronienie, regulowanie się i źródło regulacji.', 'butelkowa-zielen', 5);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('ruch/cel', 'ruch/cel', 'ruch ku, ruch od, meta, osiągnięcie, nieosiągnięcie, powrót.', 'lapis', 6);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('nasycenie/naped', 'nasycenie/napęd', '„wystarczy”, „więcej”, przesyt, głód intensywności.', 'butelkowa-zielen', 7);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('czas/ciaglosc', 'czas/ciągłość', 'trwanie, utrata, przemijanie, cykliczność, relacja z przeszłością i przyszłością.', 'lapis', 8);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('sprawczosc/przyczynowosc', 'sprawczość/przyczynowość', 'kto lub co powoduje zmianę: ja, los, inni; działanie, blokada, bezsilność, kontrola.', 'ochra', 9);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('depresyjnosc', 'depresyjność', 'ślady anhedonii, beznadziei, wycofania, wyczerpania, pustki, zaniku napędu itd.', 'terakota', 10);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('lek/gad', 'lęk/GAD', 'przewidywanie zagrożenia, zamartwianie, kontrola, sprawdzanie, hiperczujność, somatyczny alarm.', 'terakota', 11);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('maskowanie', 'maskowanie', 'zarządzanie publiczną wersją siebie i koszt tego zarządzania.', 'sliwka', 12);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('kierunek', 'kierunek', 'dokąd skierowana jest emocja, uwaga albo ruch: do siebie, do innych, ku/od świata, ku przeszłości/przyszłości.', 'sliwka', 13);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('pobudzenie/dynamika', 'pobudzenie/dynamika', 'poziom energii oraz zmiana energii w czasie: eskalacja, wygaszanie, crash, rozpad.', 'butelkowa-zielen', 14);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('dostep-do-emocji', 'dostęp-do-emocji', 'czy emocja jest nazwana, nienazwana, rozpoznawana przez ciało, skutek, opóźnienie lub inną osobę.', 'terakota', 15);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('emocja/afekt', 'emocja/afekt', 'co jest faktycznie czute: smutek, radość, lęk, nadzieja, wstyd, frustracja itd. To osobny wymiar od objawu lub mechanizmu; np. lęk może współwystąpić z lęk-antycypacyjny , ale nie są tym samym.', 'terakota', 16);
INSERT INTO axes (axis_name, label, description, family_name, sort_order) VALUES ('cialo', 'ciało', 'ciało jako nośnik doświadczenia: cielesność, dotyk, napięcie, pożądanie i sygnały somatyczne; nie każdy bodziec sensoryczny i nie każda emocja.', 'lapis', 17);

